window.WESTARIS_SEARCH_INDEX=[{"title":"Grondwet & Burgerrechten","code":"Constitution of the State of Westaris · WR-C","context":"Wetgeving","description":"De juridische basis van Westaris: Amerikaans geïnspireerd, Nederlandstalig uitgewerkt en uitsluitend bedoeld voor roleplay.","path":"grondwet/"},{"title":"Gelijkheid voor de wet","code":"WR-C §1","context":"Grondwet & Burgerrechten","description":"Iedere inwoner heeft recht op gelijke bescherming van de wet. Overheidsfunctionarissen handelen zonder willekeur en leggen besluiten uit op basis van objectieve gronden.","path":"grondwet/#wr-c-1"},{"title":"Legaliteitsbeginsel","code":"WR-C §2","context":"Grondwet & Burgerrechten","description":"Een gedraging is alleen strafbaar als zij vooraf in een geldige en gepubliceerde bepaling strafbaar is gesteld. Nieuwe wetten hebben geen terugwerkende kracht ten nadele van een verdachte.","path":"grondwet/#wr-c-2"},{"title":"Scheiding der machten","code":"WR-C §3","context":"Grondwet & Burgerrechten","description":"De wetgevende macht stelt regels vast; uitvoerende diensten handhaven de wet; de onafhankelijke rechter beslist geschillen. Geen dienst mag de rechterlijke rol zonder rechtsgrond overnemen.","path":"grondwet/#wr-c-3"},{"title":"Openbaarheid en rechtszekerheid","code":"WR-C §4","context":"Grondwet & Burgerrechten","description":"Wetten, tarieven en gebiedsaanwijzingen worden toegankelijk gepubliceerd. Een ongepubliceerde wijziging mag niet onverwacht als grond voor een sanctie worden gebruikt.","path":"grondwet/#wr-c-4"},{"title":"Vrijheid van meningsuiting en vreedzame vergadering","code":"WR-C §10","context":"Grondwet & Burgerrechten","description":"Inwoners mogen hun mening uiten, verslag doen en vreedzaam demonstreren. Concrete bedreigingen, doelbewuste intimidatie of wettelijk gemotiveerde veiligheidsbeperkingen vallen hier niet automatisch onder.","path":"grondwet/#wr-c-10"},{"title":"Bescherming tegen onredelijke doorzoekingen","code":"WR-C §11","context":"Grondwet & Burgerrechten","description":"Een huiszoeking of onderzoek van persoonlijke bezittingen vereist een geldige wettelijke uitzondering, vrijwillige toestemming of een rechterlijk bevel dat op aannemelijke gronden berust. De reikwijdte blijft beperkt tot de grond van het onderzoek.","path":"grondwet/#wr-c-11"},{"title":"Recht om te zwijgen","code":"WR-C §12","context":"Grondwet & Burgerrechten","description":"Niemand hoeft zichzelf strafrechtelijk te belasten. Een verdachte mag tijdens verhoor zwijgen; zwijgen is op zichzelf geen bewijs van schuld.","path":"grondwet/#wr-c-12"},{"title":"Recht op rechtsbijstand","code":"WR-C §13","context":"Grondwet & Burgerrechten","description":"Bij een strafrechtelijk verhoor en in een strafzaak mag de verdachte een advocaat raadplegen. Als niemand beschikbaar is, wordt de procedure redelijk gepland zonder het recht inhoudsloos te maken.","path":"grondwet/#wr-c-13"},{"title":"Eerlijk proces en onschuldpresumptie","code":"WR-C §14","context":"Grondwet & Burgerrechten","description":"Iedere verdachte wordt voor onschuldig gehouden totdat schuld is bewezen. Bij twijfel over een essentieel bestanddeel volgt geen veroordeling.","path":"grondwet/#wr-c-14"},{"title":"Evenredige straf en menselijke behandeling","code":"WR-C §15","context":"Grondwet & Burgerrechten","description":"Borgtocht, boetes en vrijheidsbeneming staan in redelijke verhouding tot de feiten. Vernederende of willekeurige bestraffing is niet toegestaan.","path":"grondwet/#wr-c-15"},{"title":"Hoor en wederhoor","code":"WR-C §16","context":"Grondwet & Burgerrechten","description":"Een verdachte of procespartij mag de beschuldiging kennen, relevant bewijs betwisten en een eigen toelichting geven. Een uitspraak vermeldt de feiten en de motivering.","path":"grondwet/#wr-c-16"},{"title":"Reikwijdte","code":"WR-C §20","context":"Grondwet & Burgerrechten","description":"De grondwet geldt voor alle in-character rechtshandelingen op de officiële Westaris-server. Out-of-character misdragingen worden uitsluitend volgens de serverregels beoordeeld.","path":"grondwet/#wr-c-20"},{"title":"Voorrang","code":"WR-C §21","context":"Grondwet & Burgerrechten","description":"Bij tegenstrijdigheid gaat de grondwet vóór gewone staats- of gemeentewetten. Een rechter kan strijdige overheidshandelingen buiten toepassing laten.","path":"grondwet/#wr-c-21"},{"title":"Wijziging","code":"WR-C §22","context":"Grondwet & Burgerrechten","description":"Een wetswijziging is pas geldig na vaststelling door het aangewezen bestuur, publicatie en vermelding van de ingangsdatum. Lopende zaken worden beoordeeld volgens de voor het feit geldende regel.","path":"grondwet/#wr-c-22"},{"title":"Westaris Penal Code","code":"Strafrecht · WPC","context":"Wetgeving","description":"Strafbare feiten, bewijsvereisten en evenwichtige straffen voor de fictieve Amerikaanse staat Westaris.","path":"wetboek/"},{"title":"Toepasselijkheid","code":"WPC §001","context":"Westaris Penal Code","description":"De Penal Code is van toepassing op strafbare handelingen binnen de staat Westaris. OOC-overtredingen worden niet als strafbaar feit berecht.","path":"wetboek/#wpc-001"},{"title":"Opzet en schuld","code":"WPC §002","context":"Westaris Penal Code","description":"Opzet houdt in dat de gedraging bewust is verricht. Voor schuldmisdrijven volstaat aantoonbare ernstige onvoorzichtigheid wanneer dit uitdrukkelijk bij het artikel is bepaald.","path":"wetboek/#wpc-002"},{"title":"Poging","code":"WPC §003","context":"Westaris Penal Code","description":"Een aantoonbare uitvoeringshandeling die rechtstreeks gericht is op het voltooien van een felony kan als poging worden vervolgd; de straf is maximaal één klasse lager dan voor het voltooide delict.","path":"wetboek/#wpc-003"},{"title":"Medeplegen en medeplichtigheid","code":"WPC §004","context":"Westaris Penal Code","description":"Wie bewust en wezenlijk bijdraagt aan een strafbaar feit kan als medepleger of medeplichtige worden vervolgd. Aanwezig zijn op een locatie is op zichzelf onvoldoende.","path":"wetboek/#wpc-004"},{"title":"Noodweer en noodtoestand","code":"WPC §005","context":"Westaris Penal Code","description":"Noodzakelijk, proportioneel handelen om een direct dreigend onrechtmatig gevaar af te wenden kan een rechtvaardiging zijn. De rechter weegt de feitelijke omstandigheden.","path":"wetboek/#wpc-005"},{"title":"Samenloop van feiten","code":"WPC §006","context":"Westaris Penal Code","description":"Verschillende strafbare gedragingen mogen afzonderlijk ten laste worden gelegd. Dezelfde handeling mag niet tweemaal onder gelijkwaardige artikelen worden bestraft.","path":"wetboek/#wpc-006"},{"title":"Strafklassen","code":"WPC §007","context":"Westaris Penal Code","description":"Infraction: uitsluitend geldboete; misdemeanor: licht misdrijf; felony: zwaar misdrijf. De concrete bovengrens volgt uit de strafmatrix en de toepasselijke bijzondere bepaling.","path":"wetboek/#wpc-007"},{"title":"Strafmatrix (RP-balans)","code":"Tabel","context":"Westaris Penal Code","description":"Fictieve spelbedragen. Een rechter kiest gemotiveerd een concrete straf binnen de toepasselijke klasse; in één zaak geldt zonder afzonderlijke uitspraak maximaal 120 RP-minuten detentie. Infraction $100 – $2.500 Geen Misdemeanor C $500 – $5.000 0 – 10 Misdemeanor B $1.000 – $10.000 0 – 20 Misdemeanor A $2.500 – $20.000 0 – 30 Felony D $10.000 – $35.000 20 – 45","path":"wetboek/"},{"title":"Diefstal","code":"WPC §101","context":"Westaris Penal Code","description":"Het opzettelijk wegnemen van een goed dat aan een ander toebehoort met het oogmerk zich dat zonder toestemming toe te eigenen.","path":"wetboek/#wpc-101"},{"title":"Inbraak","code":"WPC §102","context":"Westaris Penal Code","description":"Het zonder toestemming binnendringen in een afgesloten gebouw of voertuig met het aantoonbare doel daar een strafbaar feit te plegen.","path":"wetboek/#wpc-102"},{"title":"Overval","code":"WPC §103","context":"Westaris Penal Code","description":"Diefstal waarbij geweld of een ernstige onmiddellijke bedreiging wordt gebruikt om de buit te verkrijgen.","path":"wetboek/#wpc-103"},{"title":"Afpersing","code":"WPC §104","context":"Westaris Penal Code","description":"Iemand door onrechtmatige bedreiging dwingen geld, goederen of rechten af te staan.","path":"wetboek/#wpc-104"},{"title":"Verduistering","code":"WPC §105","context":"Westaris Penal Code","description":"Een rechtmatig toevertrouwd goed opzettelijk voor zichzelf houden of aan de rechthebbende onttrekken.","path":"wetboek/#wpc-105"},{"title":"Oplichting","code":"WPC §106","context":"Westaris Penal Code","description":"Met opzettelijke misleiding een ander bewegen tot afgifte van geld of goederen. Een teleurstellende koop is zonder bedrieglijk opzet geen oplichting.","path":"wetboek/#wpc-106"},{"title":"Heling","code":"WPC §107","context":"Westaris Penal Code","description":"Het bewust kopen, verkopen, verbergen of bezitten van goederen waarvan de illegale herkomst aannemelijk bewezen is.","path":"wetboek/#wpc-107"},{"title":"Witwassen","code":"WPC §108","context":"Westaris Penal Code","description":"Het opzettelijk verhullen van de criminele herkomst of werkelijke eigenaar van geld of vermogen. Alleen contant geld bezitten vormt geen bewijs.","path":"wetboek/#wpc-108"},{"title":"Vervalsing van documenten","code":"WPC §109","context":"Westaris Penal Code","description":"Het bewust vervalsen of gebruiken van identiteits-, eigendoms-, vergunning- of financiële documenten om een rechtsgevolg te bereiken.","path":"wetboek/#wpc-109"},{"title":"Schade aan eigendom","code":"WPC §110","context":"Westaris Penal Code","description":"Het opzettelijk vernielen of beschadigen van andermans eigendom zonder toestemming.","path":"wetboek/#wpc-110"},{"title":"Fraude bij handel","code":"WPC §111","context":"Westaris Penal Code","description":"Het opzettelijk misleiden over eigendom, prijsbetaling of levering met als doel onrechtmatig voordeel te verkrijgen.","path":"wetboek/#wpc-111"},{"title":"Bedreiging","code":"WPC §201","context":"Westaris Penal Code","description":"Een concrete, geloofwaardige uiting of handeling die een ander redelijkerwijs laat vrezen voor onmiddellijk onrechtmatig geweld.","path":"wetboek/#wpc-201"},{"title":"Eenvoudige mishandeling","code":"WPC §202","context":"Westaris Penal Code","description":"Het opzettelijk toepassen van onrechtmatig geweld tegen een ander.","path":"wetboek/#wpc-202"},{"title":"Zware mishandeling","code":"WPC §203","context":"Westaris Penal Code","description":"Het opzettelijk veroorzaken van aantoonbaar ernstig lichamelijk letsel.","path":"wetboek/#wpc-203"},{"title":"Vrijheidsberoving","code":"WPC §204","context":"Westaris Penal Code","description":"Een persoon zonder wettelijke bevoegdheid of geldige toestemming tegen zijn wil vastzetten of vasthouden.","path":"wetboek/#wpc-204"},{"title":"Ontvoering","code":"WPC §205","context":"Westaris Penal Code","description":"Een persoon onder dwang of misleiding naar een andere locatie brengen met het doel hem of haar de bewegingsvrijheid te ontnemen.","path":"wetboek/#wpc-205"},{"title":"Doodslag","code":"WPC §206","context":"Westaris Penal Code","description":"Het opzettelijk veroorzaken van de dood van een ander zonder bewezen voorbedachte raad.","path":"wetboek/#wpc-206"},{"title":"Moord","code":"WPC §207","context":"Westaris Penal Code","description":"Het opzettelijk veroorzaken van de dood van een ander met aantoonbare voorbedachte raad.","path":"wetboek/#wpc-207"},{"title":"Dood door grove nalatigheid","code":"WPC §208","context":"Westaris Penal Code","description":"Het door ernstige, verwijtbare onvoorzichtigheid veroorzaken van de dood van een ander zonder opzet daarop.","path":"wetboek/#wpc-208"},{"title":"Intimidatie en stalking","code":"WPC §209","context":"Westaris Penal Code","description":"Herhaald, ongewenst gedrag dat gericht is op bedreiging of ernstige verstoring van de persoonlijke veiligheid.","path":"wetboek/#wpc-209"},{"title":"Gevaarzetting","code":"WPC §210","context":"Westaris Penal Code","description":"Door ernstig roekeloos handelen een concreet en onmiddellijk risico op ernstig letsel voor anderen veroorzaken.","path":"wetboek/#wpc-210"},{"title":"Verzet bij rechtmatige arrestatie","code":"WPC §301","context":"Westaris Penal Code","description":"Het actief met geweld tegenwerken van een duidelijk aangekondigde rechtmatige arrestatie. Vragen stellen of zwijgen is geen verzet.","path":"wetboek/#wpc-301"},{"title":"Obstructie van justitie","code":"WPC §302","context":"Westaris Penal Code","description":"Het opzettelijk belemmeren van een concreet rechtmatig onderzoek, bijvoorbeeld door bewijsmateriaal doelbewust te vernietigen.","path":"wetboek/#wpc-302"},{"title":"Zich voordoen als ambtenaar","code":"WPC §303","context":"Westaris Penal Code","description":"Het misleidend uitoefenen of voorwenden van politie-, justitie- of andere overheidsbevoegdheden zonder bevoegdheid.","path":"wetboek/#wpc-303"},{"title":"Omkoopbaarheid en omkoping","code":"WPC §304","context":"Westaris Penal Code","description":"Een overheidsfunctionaris of derde biedt, verlangt of accepteert voordeel om een ambtshandeling onrechtmatig te beïnvloeden.","path":"wetboek/#wpc-304"},{"title":"Misbruik van ambt","code":"WPC §305","context":"Westaris Penal Code","description":"Een ambtenaar gebruikt bewust een officiële bevoegdheid voor persoonlijk gewin of tegen beter weten in buiten het wettelijk doel.","path":"wetboek/#wpc-305"},{"title":"Valsheid in een officiële verklaring","code":"WPC §306","context":"Westaris Penal Code","description":"Opzettelijk een wezenlijk onjuiste verklaring afleggen in een formele strafrechtelijke of bestuurlijke procedure.","path":"wetboek/#wpc-306"},{"title":"Schending van huisvrede","code":"WPC §307","context":"Westaris Penal Code","description":"Een woning of bedrijfspand zonder toestemming binnengaan of na duidelijk verzoek tot vertrek zonder rechtsgrond blijven.","path":"wetboek/#wpc-307"},{"title":"Betreden beveiligd terrein","code":"WPC §308","context":"Westaris Penal Code","description":"Een duidelijk aangegeven afgesloten overheids- of veiligheidslocatie zonder toestemming betreden.","path":"wetboek/#wpc-308"},{"title":"Criminele organisatie","code":"WPC §309","context":"Westaris Penal Code","description":"Duurzaam en aantoonbaar samenwerken met het doel meerdere zware misdrijven te plegen. Louter groepslidmaatschap volstaat niet.","path":"wetboek/#wpc-309"},{"title":"Openbare ordeverstoring","code":"WPC §310","context":"Westaris Penal Code","description":"Opzettelijk en ernstig ontregelen van een publieke plaats ondanks een rechtmatige, duidelijke aanwijzing om te stoppen.","path":"wetboek/#wpc-310"},{"title":"Ontsnapping uit rechtmatige detentie","code":"WPC §311","context":"Westaris Penal Code","description":"Het opzettelijk zonder bevoegdheid verlaten van een door een bevoegde instantie opgelegde vrijheidsbeneming.","path":"wetboek/#wpc-311"},{"title":"Onrechtmatige vrijheidsbeneming door ambtenaar","code":"WPC §312","context":"Westaris Penal Code","description":"Een overheidsmedewerker houdt iemand bewust zonder toereikende wettelijke grond vast.","path":"wetboek/#wpc-312"},{"title":"Illegale wapenhandel","code":"WPC §401","context":"Westaris Penal Code","description":"Het bedrijfsmatig of herhaaldelijk overdragen van verboden wapens of munitie zonder de vereiste toestemming.","path":"wetboek/#wpc-401"},{"title":"Illegale distributie van verboden middelen","code":"WPC §402","context":"Westaris Penal Code","description":"Het aantoonbaar verkopen of verspreiden van verboden verdovende middelen in strijd met de Westaris Controlled Substances Act.","path":"wetboek/#wpc-402"},{"title":"Onrechtmatige kansspelen","code":"WPC §403","context":"Westaris Penal Code","description":"Het organiseren van een commercieel kansspel zonder de vereiste vergunning of buiten de vergunningsvoorwaarden.","path":"wetboek/#wpc-403"},{"title":"Illegale bedrijfsuitoefening","code":"WPC §404","context":"Westaris Penal Code","description":"Het bewust exploiteren van een vergunningsplichtige onderneming na formele waarschuwing zonder vereiste bedrijfsvergunning.","path":"wetboek/#wpc-404"},{"title":"Bewijsvervalsing","code":"WPC §405","context":"Westaris Penal Code","description":"Het opzettelijk creëren of manipuleren van materieel bewijs om een onderzoek of rechtspraak te misleiden.","path":"wetboek/#wpc-405"},{"title":"Straftoemeting","code":"WPC §501","context":"Westaris Penal Code","description":"De officier vordert een passende straf. De rechter weegt ernst, opzet, bewezen schade, verzachtende omstandigheden, herhaling en medewerking. De strafklasse vormt de grens.","path":"wetboek/#wpc-501"},{"title":"Beslag en verbeurdverklaring","code":"WPC §502","context":"Westaris Penal Code","description":"Voorwerpen kunnen alleen met rechtmatige grondslag worden veiliggesteld. Definitieve verbeurdverklaring van rechtmatig eigendom vereist een gemotiveerde beslissing.","path":"wetboek/#wpc-502"},{"title":"Schadevergoeding","code":"WPC §503","context":"Westaris Penal Code","description":"Een slachtoffer kan aannemelijke directe schade vorderen. De civiele vordering staat los van de geldboete en wordt door de rechter getoetst.","path":"wetboek/#wpc-503"},{"title":"Strafblad en rehabilitatie","code":"WPC §504","context":"Westaris Penal Code","description":"Een definitieve veroordeling mag op het IC-strafblad komen. Vrijspraak en vervallen verdenkingen worden niet als veroordeling geregistreerd.","path":"wetboek/#wpc-504"},{"title":"Beroep","code":"WPC §505","context":"Westaris Penal Code","description":"Tegen een veroordeling kan volgens het procesreglement beroep worden ingesteld. Het beroep wordt beoordeeld door een andere, onafhankelijke rechter.","path":"wetboek/#wpc-505"},{"title":"Criminal Procedure Code","code":"Strafprocesrecht · WCPC","context":"Wetgeving","description":"Nederlandstalige vertaling van Amerikaanse strafprocesprincipes, geschikt gemaakt voor praktische roleplay.","path":"strafvordering/"},{"title":"Vrijwillig gesprek","code":"WCPC §101","context":"Criminal Procedure Code","description":"Een inwoner mag bij een vrijwillig gesprek vragen of hij vrij is om te vertrekken. Vrijwilligheid eindigt zodra de betrokkene feitelijk niet meer mag weggaan.","path":"strafvordering/#wcpc-101"},{"title":"Tijdelijke staandehouding","code":"WCPC §102","context":"Criminal Procedure Code","description":"Een korte controle vereist concrete, benoembare feiten die een redelijk vermoeden van een overtreding ondersteunen; deze controle geeft geen onbeperkte onderzoeksbevoegdheid.","path":"strafvordering/#wcpc-102"},{"title":"Arrestatie","code":"WCPC §103","context":"Criminal Procedure Code","description":"Een arrestatie vereist probable cause: feiten die redelijkerwijs aannemelijk maken dat de betrokkene een strafbaar feit beging. De agent deelt de reden binnen redelijke tijd mee.","path":"strafvordering/#wcpc-103"},{"title":"Identificatie","code":"WCPC §104","context":"Criminal Procedure Code","description":"Een identiteitscontrole heeft een objectieve grond nodig, bijvoorbeeld een rechtmatige verkeersstop, strafrechtelijk onderzoek of wettelijk afgebakende toegangscontrole.","path":"strafvordering/#wcpc-104"},{"title":"Gebruik van dwang","code":"WCPC §105","context":"Criminal Procedure Code","description":"Dwang is uitsluitend toegestaan voor een rechtmatig doel, wanneer nodig en zo beperkt mogelijk. Na beëindiging van verzet vervalt de rechtvaardiging voor extra dwang.","path":"strafvordering/#wcpc-105"},{"title":"Search warrant","code":"WCPC §201","context":"Criminal Procedure Code","description":"Een huiszoekingsbevel vermeldt locatie, doel, eventuele voorwerpen en de feiten die de rechter overtuigen van probable cause. Een algemeen bevel zonder begrenzing is ongeldig.","path":"strafvordering/#wcpc-201"},{"title":"Toestemming voor onderzoek","code":"WCPC §202","context":"Criminal Procedure Code","description":"Toestemming moet vrijwillig, duidelijk en specifiek zijn. De betrokkene mag de toestemming beperken of intrekken voor nog niet onderzochte delen.","path":"strafvordering/#wcpc-202"},{"title":"Veiligheidsfouillering","code":"WCPC §203","context":"Criminal Procedure Code","description":"Bij een gegronde verdenking van direct gevaar mag een beperkte veiligheidscontrole worden uitgevoerd. Deze is geen algemene zoektocht naar bewijs.","path":"strafvordering/#wcpc-203"},{"title":"Onderzoek voertuig","code":"WCPC §204","context":"Criminal Procedure Code","description":"Een voertuigonderzoek vereist toestemming, een geldig bevel of een aantoonbare wettelijke uitzondering. Alleen een verkeersstop is geen automatische grond voor een volledige doorzoeking.","path":"strafvordering/#wcpc-204"},{"title":"Spoedeisende uitzondering","code":"WCPC §205","context":"Criminal Procedure Code","description":"Bij een onmiddellijke noodsituatie, zoals acuut gevaar voor personen, mag zonder voorafgaand bevel uitsluitend worden gehandeld voor zover nodig om dat gevaar te beëindigen.","path":"strafvordering/#wcpc-205"},{"title":"Bewijsketen","code":"WCPC §206","context":"Criminal Procedure Code","description":"Voor elk relevant voorwerp of digitaal bestand worden vindplaats, tijdstip, verzamelende ambtenaar en iedere overdracht vastgelegd voor zover de RP-systemen dit ondersteunen.","path":"strafvordering/#wcpc-206"},{"title":"Beeldmateriaal en getuigen","code":"WCPC §207","context":"Criminal Procedure Code","description":"Videobeelden, bodycam, verklaringen en documenten kunnen bewijs vormen wanneer authenticiteit en context voldoende kunnen worden getoetst.","path":"strafvordering/#wcpc-207"},{"title":"Miranda-waarschuwing","code":"WCPC §301","context":"Criminal Procedure Code","description":"Vóór een inhoudelijk verhoor van een in detentie gehouden verdachte meldt de verhoorder: recht om te zwijgen, dat verklaringen gebruikt kunnen worden en recht op een advocaat.","path":"strafvordering/#wcpc-301"},{"title":"Verzoek om advocaat","code":"WCPC §302","context":"Criminal Procedure Code","description":"Bij een ondubbelzinnig verzoek om rechtsbijstand wordt het inhoudelijke verhoor onderbroken totdat een reële mogelijkheid tot overleg is geboden.","path":"strafvordering/#wcpc-302"},{"title":"Geen afgedwongen verklaring","code":"WCPC §303","context":"Criminal Procedure Code","description":"Verklaringen verkregen door bedreiging, onbevoegde druk of misleiding die fundamentele rechten aantast, kunnen door de rechter worden uitgesloten.","path":"strafvordering/#wcpc-303"},{"title":"Proces-verbaal en dossier","code":"WCPC §304","context":"Criminal Procedure Code","description":"De politie legt tijdlijn, feiten, verdenkingen, bewijs, aanwezigen en genomen maatregelen controleerbaar vast. De verdediging ontvangt het voor de zaak relevante dossier.","path":"strafvordering/#wcpc-304"},{"title":"Aanklacht","code":"WCPC §305","context":"Criminal Procedure Code","description":"Het District Attorney’s Office beslist of vervolging passend is, formuleert de feiten en noemt de toepasselijke WPC- of andere wetsartikelen.","path":"strafvordering/#wcpc-305"},{"title":"Voorlopige vrijlating en borgtocht","code":"WCPC §306","context":"Criminal Procedure Code","description":"De rechter kan vrijlating, voorwaarden of proportionele borgtocht bepalen. Een borgsom is geen automatische straf en mag niet buitensporig zijn.","path":"strafvordering/#wcpc-306"},{"title":"Voorgeleiding en zitting","code":"WCPC §401","context":"Criminal Procedure Code","description":"De beschuldiging en relevante bewijsstukken worden aan de betrokkene bekendgemaakt. Voldoende voorbereidingstijd wordt overeengekomen binnen de beschikbare RP-capaciteit.","path":"strafvordering/#wcpc-401"},{"title":"Bewijsmaatstaf","code":"WCPC §402","context":"Criminal Procedure Code","description":"Voor een strafrechtelijke veroordeling moet de rechter buiten redelijke twijfel overtuigd zijn dat ieder essentieel bestanddeel bewezen is.","path":"strafvordering/#wcpc-402"},{"title":"Uitspraak","code":"WCPC §403","context":"Criminal Procedure Code","description":"Een vonnis bevat bewezen feiten, niet-bewezen feiten, toepasselijke wet, eventuele straf en beknopte motivering.","path":"strafvordering/#wcpc-403"},{"title":"Beroep en herziening","code":"WCPC §404","context":"Criminal Procedure Code","description":"Hoger beroep wordt onafhankelijk behandeld. Nieuw doorslaggevend bewijs kan reden zijn voor herziening volgens een gemotiveerde beslissing.","path":"strafvordering/#wcpc-404"},{"title":"Onrechtmatig verkregen bewijs","code":"WCPC §405","context":"Criminal Procedure Code","description":"De rechter beoordeelt de ernst van de schending, het effect op de eerlijkheid van het proces en of uitsluiting of een ander rechtsgevolg passend is.","path":"strafvordering/#wcpc-405"},{"title":"Westaris Vehicle Code","code":"Verkeerswet · WVC","context":"Wetgeving","description":"Een herkenbare Amerikaanse verkeerswet met mph, duidelijke rijregels en transparante boetetabellen.","path":"verkeerswet/"},{"title":"Veilig rijgedrag","code":"WVC §101","context":"Westaris Vehicle Code","description":"Bestuurders houden rekening met omstandigheden en andere weggebruikers. Roekeloos slingeren, gevaarlijk inhalen of gevaarlijke acties zijn strafbaar.","path":"verkeerswet/#wvc-101"},{"title":"Rijbewijs en voertuigpapieren","code":"WVC §102","context":"Westaris Vehicle Code","description":"Het besturen van een vergunningplichtig voertuig vereist de juiste categorie rijbewijs. Een bestuurder werkt mee aan een rechtmatige verkeerscontrole.","path":"verkeerswet/#wvc-102"},{"title":"Verkeerslichten en voorrang","code":"WVC §103","context":"Westaris Vehicle Code","description":"Rood licht betekent stoppen; stopborden vereisen daadwerkelijk stoppen. Voorrang wordt verleend volgens tekens en verkeerssituatie.","path":"verkeerswet/#wvc-103"},{"title":"Voertuigveiligheid","code":"WVC §104","context":"Westaris Vehicle Code","description":"Een voertuig heeft werkende essentiële verlichting, remmen en een leesbaar kenteken. Gevaarlijke technische gebreken kunnen tot tijdelijk rijverbod leiden.","path":"verkeerswet/#wvc-104"},{"title":"Parkeren","code":"WVC §105","context":"Westaris Vehicle Code","description":"Parkeren op een noodroute, brandweertoegang of gehandicaptenplaats zonder rechtvaardiging is verboden.","path":"verkeerswet/#wvc-105"},{"title":"Hulpdiensten","code":"WVC §106","context":"Westaris Vehicle Code","description":"Een bestuurder maakt veilig ruimte voor voertuigen met geactiveerde optische en geluidssignalen. Signalen verlenen geen onbeperkt recht op gevaarlijk rijgedrag.","path":"verkeerswet/#wvc-106"},{"title":"Standaard snelheidslimieten","code":"Tabel","context":"Westaris Vehicle Code","description":" Binnen bebouwde kom 35 mph Buitenweg / county road 55 mph Highway / interstate 65 mph Schoolzone indien aangeduid 20 mph","path":"verkeerswet/"},{"title":"Snelheidsboetes","code":"Tabel","context":"Westaris Vehicle Code","description":" 1–9 mph $250 Infraction 10–19 mph $750 Infraction 20–29 mph $1.500 Infraction 30 mph of meer $2.500 Infraction + mogelijke verdenking WVC §201","path":"verkeerswet/"},{"title":"Roekeloos rijden","code":"WVC §201","context":"Westaris Vehicle Code","description":"Een bestuurder schept door bewuste, ernstige onvoorzichtigheid concreet gevaar voor anderen. Alleen een snelheidsmeting bewijst niet automatisch roekeloosheid.","path":"verkeerswet/#wvc-201"},{"title":"Rijden onder invloed","code":"WVC §202","context":"Westaris Vehicle Code","description":"Besturen terwijl het rijvermogen aantoonbaar door alcohol of middelen is aangetast; een controle of test moet binnen de roleplay zorgvuldig worden onderbouwd.","path":"verkeerswet/#wvc-202"},{"title":"Ongeval verlaten","code":"WVC §203","context":"Westaris Vehicle Code","description":"Wie betrokken is bij een ongeval met schade of letsel stopt veilig en wisselt gegevens uit of schakelt hulpdiensten in.","path":"verkeerswet/#wvc-203"},{"title":"Rijden tijdens schorsing","code":"WVC §204","context":"Westaris Vehicle Code","description":"Een bestuurder die weet dat zijn bevoegdheid is geschorst, bestuurt toch een vergunningplichtig voertuig.","path":"verkeerswet/#wvc-204"},{"title":"Straatraces","code":"WVC §205","context":"Westaris Vehicle Code","description":"Zonder ontheffing op de openbare weg een snelheidswedstrijd organiseren of daaraan deelnemen.","path":"verkeerswet/#wvc-205"},{"title":"Gevaarlijke achtervolging","code":"WVC §206","context":"Westaris Vehicle Code","description":"Bewust vluchtgedrag waarbij de bestuurder een concreet ernstig gevaar veroorzaakt. De feiten moeten los van de enkele vlucht worden onderbouwd.","path":"verkeerswet/#wvc-206"},{"title":"Kentekenregistratie","code":"WVC §301","context":"Westaris Vehicle Code","description":"Voertuigen die op de openbare weg worden gebruikt moeten geldig geregistreerd zijn en een herkenbaar kenteken dragen.","path":"verkeerswet/#wvc-301"},{"title":"Offroadgebruik","code":"WVC §302","context":"Westaris Vehicle Code","description":"Op openbaar natuurterrein rijden mag alleen op daarvoor aangewezen routes en met geschikte, toegelaten voertuigen.","path":"verkeerswet/#wvc-302"},{"title":"Inbeslagname voertuig","code":"WVC §303","context":"Westaris Vehicle Code","description":"Een auto wordt niet louter als extra straf afgepakt. Er is een wettelijke grond voor beslag, bewaring of rechterlijke verbeurdverklaring vereist.","path":"verkeerswet/#wvc-303"},{"title":"Dienstvoertuigen","code":"WVC §304","context":"Westaris Vehicle Code","description":"Voertuigen van politie, EMS en andere diensten mogen alleen met bevoegdheid voor hun dienstdoel worden gebruikt. Misbruik kan tot disciplinaire en strafrechtelijke gevolgen leiden.","path":"verkeerswet/#wvc-304"},{"title":"Firearms & Weapons Act","code":"Wapenwet · WFWA","context":"Wetgeving","description":"Fictief Amerikaans vergunningenmodel met heldere grenzen aan bezit, dragen en handel.","path":"wapenwet/"},{"title":"Verboden voorwerpen","code":"WFWA §101","context":"Firearms & Weapons Act","description":"Een door de staat verboden wapen of gevaarlijk voorwerp mag niet zonder uitdrukkelijke bevoegdheid worden gedragen, overgedragen of opgeslagen.","path":"wapenwet/#wfwa-101"},{"title":"Geregistreerde vuurwapens","code":"WFWA §102","context":"Firearms & Weapons Act","description":"Voor aangewezen vuurwapencategorieën is een geldige staatsvergunning vereist. De registratie moet controleerbaar op de persoon staan.","path":"wapenwet/#wfwa-102"},{"title":"Dragen in openbare ruimte","code":"WFWA §103","context":"Firearms & Weapons Act","description":"Een bezit- of registratiebewijs geeft niet automatisch toestemming om een wapen op iedere locatie te dragen. Veiligheidszones kunnen nader begrenzen.","path":"wapenwet/#wfwa-103"},{"title":"Onbevoegde munitie","code":"WFWA §104","context":"Firearms & Weapons Act","description":"Voor munitie gelden dezelfde beperkingen voor rechtmatig bezit en overdracht als voor de categorie waartoe die behoort.","path":"wapenwet/#wfwa-104"},{"title":"Replica en imitatie","code":"WFWA §105","context":"Firearms & Weapons Act","description":"Een imitatie die bewust als echt wapen wordt gebruikt om iemand te bedreigen, kan onder de strafbepalingen over bedreiging of afpersing vallen.","path":"wapenwet/#wfwa-105"},{"title":"Vergunningverlening","code":"WFWA §201","context":"Firearms & Weapons Act","description":"Alleen het daartoe aangewezen staatsloket kan vergunningen afgeven. Een weigering of intrekking krijgt een concrete, controleerbare reden.","path":"wapenwet/#wfwa-201"},{"title":"Overdracht","code":"WFWA §202","context":"Firearms & Weapons Act","description":"Legale overdracht vereist dat beide partijen bevoegd zijn en een verplichte registratie wordt bijgewerkt.","path":"wapenwet/#wfwa-202"},{"title":"Handel zonder vergunning","code":"WFWA §203","context":"Firearms & Weapons Act","description":"Het als handelaar zonder benodigde vergunning aanbieden of verkopen van geregistreerde of verboden wapens is strafbaar.","path":"wapenwet/#wfwa-203"},{"title":"Beslag en teruggave","code":"WFWA §204","context":"Firearms & Weapons Act","description":"Wapens worden alleen rechtmatig in beslag genomen wanneer zij bewijs vormen, verboden zijn of een concreet veiligheidsrisico vormen. Teruggave vindt plaats na het vervallen van de grond.","path":"wapenwet/#wfwa-204"},{"title":"Onzorgvuldig gebruik","code":"WFWA §301","context":"Firearms & Weapons Act","description":"Een wapen zonder rechtvaardiging gebruiken op een wijze die concreet gevaar veroorzaakt is strafbaar, los van een eventueel geweldsdelict.","path":"wapenwet/#wfwa-301"},{"title":"Dienstwapens","code":"WFWA §302","context":"Firearms & Weapons Act","description":"Een dienstwapen is alleen toegestaan tijdens of op grond van de officieel vastgelegde bevoegdheid van de betreffende functie.","path":"wapenwet/#wfwa-302"},{"title":"Controlled Substances Act","code":"Verdovende middelen · WCSA","context":"Wetgeving","description":"Duidelijke fictieve regelgeving over verboden middelen met nadruk op aantoonbaar bewijs.","path":"drugswet/"},{"title":"Gereguleerde middelen","code":"WCSA §101","context":"Controlled Substances Act","description":"De overheid publiceert welke middelen verboden, receptplichtig of toegelaten zijn. Een niet-gepubliceerde productnaam vormt geen zelfstandige strafgrond.","path":"drugswet/#wcsa-101"},{"title":"Illegaal bezit","code":"WCSA §102","context":"Controlled Substances Act","description":"Het bewust zonder rechtsgrond bezitten van een op de verboden lijst geplaatst middel.","path":"drugswet/#wcsa-102"},{"title":"Handel en distributie","code":"WCSA §103","context":"Controlled Substances Act","description":"Het zonder bevoegdheid verkopen of verspreiden van middelen die volgens de staatslijst verboden zijn.","path":"drugswet/#wcsa-103"},{"title":"Productie","code":"WCSA §104","context":"Controlled Substances Act","description":"Het onbevoegd vervaardigen of verwerken van verboden stoffen met het doel ze te verspreiden.","path":"drugswet/#wcsa-104"},{"title":"Noodzakelijke medische handelingen","code":"WCSA §105","context":"Controlled Substances Act","description":"Wettig handelen door bevoegde medische medewerkers binnen hun functie wordt niet vervolgd als crimineel bezit.","path":"drugswet/#wcsa-105"},{"title":"Cannabisbeleid","code":"WCSA §106","context":"Controlled Substances Act","description":"Cannabis is in Westaris alleen toegestaan voor zover een afzonderlijk gepubliceerd staatsbesluit dit regelt. Zonder zo’n besluit gelden de algemene bepalingen over verboden middelen.","path":"drugswet/#wcsa-106"},{"title":"Bewijs en herkomst","code":"WCSA §201","context":"Controlled Substances Act","description":"Voor een veroordeling moet aannemelijk worden vastgesteld welk middel aanwezig was, wie bewust beschikking had en welke verbodsbepaling geldt.","path":"drugswet/#wcsa-201"},{"title":"Beslag","code":"WCSA §202","context":"Controlled Substances Act","description":"Onrechtmatig aanwezige middelen kunnen als bewijs worden bewaard en na rechtsgeldig besluit worden vernietigd; de bewijsketen wordt vastgelegd.","path":"drugswet/#wcsa-202"},{"title":"Meervoudige kwalificatie","code":"WCSA §203","context":"Controlled Substances Act","description":"Eenzelfde hoeveelheid mag niet zonder aanvullend bewijs tegelijk uitsluitend wegens bezit én dezelfde overdracht dubbel worden bestraft.","path":"drugswet/#wcsa-203"},{"title":"Westaris Municipal Code","code":"Gemeentelijke verordeningen · WMC","context":"Bestuur & RP","description":"Heldere gemeentelijke regels voor openbare orde, evenementen en leefbaarheid, afzonderlijk van de OOC-serverregels.","path":"apv/"},{"title":"Openbare orde","code":"WMC §101","context":"Westaris Municipal Code","description":"Het opzettelijk en ernstig verstoren van een openbare locatie kan na duidelijke, rechtmatige waarschuwing worden beboet.","path":"apv/#wmc-101"},{"title":"Geluidsoverlast","code":"WMC §102","context":"Westaris Municipal Code","description":"Langdurig en aantoonbaar hinderlijk geluid op een openbare plek na een redelijk verzoek om vermindering.","path":"apv/#wmc-102"},{"title":"Vervuiling en afval","code":"WMC §103","context":"Westaris Municipal Code","description":"Opzettelijk dumpen van afval op openbare wegen, parken of waterwegen zonder vergunning.","path":"apv/#wmc-103"},{"title":"Demonstraties","code":"WMC §104","context":"Westaris Municipal Code","description":"Vreedzame demonstraties zijn toegestaan. Voor grote geplande bijeenkomsten kan een verkeers- of veiligheidsplan nodig zijn zonder de inhoud van de boodschap te censureren.","path":"apv/#wmc-104"},{"title":"Evenementenvergunning","code":"WMC §105","context":"Westaris Municipal Code","description":"Een grootschalig evenement met afsluiting van publieke wegen heeft voorafgaande toestemming nodig.","path":"apv/#wmc-105"},{"title":"Illegale verkoop op straat","code":"WMC §106","context":"Westaris Municipal Code","description":"Structurele commerciële straatverkoop op locaties waar een gepubliceerde vergunning vereist is.","path":"apv/#wmc-106"},{"title":"Afgesloten terreinen","code":"WMC §201","context":"Westaris Municipal Code","description":"Bij duidelijk aangegeven openbare veiligheidszones zijn toegang en parkeren onderworpen aan gepubliceerde, redelijke regels.","path":"apv/#wmc-201"},{"title":"Openbare dronkenschap met overlast","code":"WMC §202","context":"Westaris Municipal Code","description":"Enkel alcoholgebruik is niet voldoende. Aantoonbare hinder, gevaar of verstoring door intoxicatie kan een overtreding zijn.","path":"apv/#wmc-202"},{"title":"Gevaarlijk gedrag in parken","code":"WMC §203","context":"Westaris Municipal Code","description":"Het creëren van een concreet gevaar voor omstanders of natuur in een als openbaar park aangewezen gebied.","path":"apv/#wmc-203"},{"title":"Dierenwelzijn","code":"WMC §204","context":"Westaris Municipal Code","description":"Het in RP bewust verwaarlozen of mishandelen van dieren valt onder de toepasselijke regels en kan aanleiding zijn voor toezicht.","path":"apv/#wmc-204"},{"title":"Bescherming hulpdiensten","code":"WMC §205","context":"Westaris Municipal Code","description":"Toegangen tot ziekenhuizen, brandweerposten en noodroutes moeten vrij blijven, voor zover zichtbaar en aangegeven.","path":"apv/#wmc-205"},{"title":"Redelijke aanwijzing","code":"WMC §301","context":"Westaris Municipal Code","description":"Een bevoegde ambtenaar mag ter beëindiging van een concrete openbare-ordeverstoring een duidelijke en proportionele aanwijzing geven.","path":"apv/#wmc-301"},{"title":"Boetebevoegdheid","code":"WMC §302","context":"Westaris Municipal Code","description":"Alleen bevoegde functionarissen leggen IC-boetes op. Feitcode, datum en korte onderbouwing worden vermeld.","path":"apv/#wmc-302"},{"title":"Bezwaar","code":"WMC §303","context":"Westaris Municipal Code","description":"Een inwoner kan volgens het gemeentelijk procesreglement bezwaar indienen tegen een boete of ontheffingsbesluit.","path":"apv/#wmc-303"},{"title":"Roleplay & Serverregels","code":"OOC-reglement · WRR","context":"Bestuur & RP","description":"De regels voor spelers en staff, apart van de wetboeken die binnen het personagespel gelden.","path":"serverregels/"},{"title":"Respectvolle omgang","code":"WRR §01","context":"Roleplay & Serverregels","description":"Behandel medespelers en staff met respect. Discriminatie, intimidatie, doxing, gerichte pestacties en ernstige beledigingen zijn niet toegestaan.","path":"serverregels/#wrr-01"},{"title":"Geen cheats of misbruik","code":"WRR §02","context":"Roleplay & Serverregels","description":"Cheats, ongeautoriseerde software, opzettelijk gebruik van bugs en omzeilen van beveiliging zijn verboden. Meld ontdekte exploits in een supportticket.","path":"serverregels/#wrr-02"},{"title":"Geen metagaming","code":"WRR §03","context":"Roleplay & Serverregels","description":"Gebruik informatie die je personage niet op een geldige IC-manier heeft gekregen niet om voordeel te behalen.","path":"serverregels/#wrr-03"},{"title":"Geen powergaming","code":"WRR §04","context":"Roleplay & Serverregels","description":"Dwing anderen geen onontkoombare acties of uitkomsten op die geen redelijke ruimte voor tegenspel bieden.","path":"serverregels/#wrr-04"},{"title":"Geen FailRP","code":"WRR §05","context":"Roleplay & Serverregels","description":"Speel situaties geloofwaardig uit binnen de afgesproken spelwereld. Vermijd opzettelijke acties die een scène onnodig verstoren.","path":"serverregels/#wrr-05"},{"title":"Value of Life","code":"WRR §06","context":"Roleplay & Serverregels","description":"Laat je personage aannemelijk rekening houden met gevaar en de gevolgen van keuzes; niemand hoeft onredelijk elk risico te vermijden.","path":"serverregels/#wrr-06"},{"title":"RDM en VDM","code":"WRR §07","context":"Roleplay & Serverregels","description":"Geweld zonder deugdelijke RP-aanleiding en het inzetten van een voertuig als willekeurig middel tegen spelers zijn verboden.","path":"serverregels/#wrr-07"},{"title":"Combat logging","code":"WRR §08","context":"Roleplay & Serverregels","description":"Een actieve scène verlaten om aan de gevolgen ervan te ontkomen is verboden. Bij crash of storing meld je dit via support.","path":"serverregels/#wrr-08"},{"title":"New Life Rule","code":"WRR §09","context":"Roleplay & Serverregels","description":"Na een afgeronde situatie waarin het personage RP-technisch bewusteloos was, gebruik je geen onverklaarde herinneringen of kennis uit die scène.","path":"serverregels/#wrr-09"},{"title":"OOC versus IC","code":"WRR §10","context":"Roleplay & Serverregels","description":"Vermeng conflicten tussen spelers niet met die tussen personages. Staffzaken worden OOC besproken.","path":"serverregels/#wrr-10"},{"title":"Microfoon en verstaanbaarheid","code":"WRR §11","context":"Roleplay & Serverregels","description":"Een werkende, verstaanbare microfoon is nodig voor spraak-RP. Gebruik geen storende audio, soundboards of langdurig geschreeuw.","path":"serverregels/#wrr-11"},{"title":"Nederlands als voertaal","code":"WRR §12","context":"Roleplay & Serverregels","description":"Nederlands is de standaardtaal van de server. Korte andere talen passen alleen wanneer alle betrokkenen de situatie nog kunnen volgen.","path":"serverregels/#wrr-12"},{"title":"Karakterwissel","code":"WRR §13","context":"Roleplay & Serverregels","description":"Extra personages mogen niet gebruikt worden om goederen, rechten of IC-kennis oneerlijk over te dragen of een sanctie te ontwijken.","path":"serverregels/#wrr-13"},{"title":"Overvallen en gijzelingen","code":"WRR §14","context":"Roleplay & Serverregels","description":"Criminele scènes vereisen een duidelijke RP-aanleiding en eerlijke interactie. Staff kan redelijke scenario- en veiligheidsgrenzen publiceren.","path":"serverregels/#wrr-14"},{"title":"Functiekleding en dienstmiddelen","code":"WRR §15","context":"Roleplay & Serverregels","description":"Overheidskleding, dienstmiddelen en speciale voertuigen gebruik je alleen met passende functie of goedgekeurde RP-toestemming.","path":"serverregels/#wrr-15"},{"title":"Geen streamsniping","code":"WRR §16","context":"Roleplay & Serverregels","description":"Gebruik geen livestream, clip, chat of externe communicatie om actuele in-game locaties of informatie van anderen te ontdekken.","path":"serverregels/#wrr-16"},{"title":"Geen misbruik van veilige zones","code":"WRR §17","context":"Roleplay & Serverregels","description":"Veilige zones beschermen normale interacties. Gebruik deze niet om bewust voordeel uit actieve achtervolgingen of conflicten te halen.","path":"serverregels/#wrr-17"},{"title":"Geen overmatig OOC-spam","code":"WRR §18","context":"Roleplay & Serverregels","description":"Spam, ongewenste reclame en moedwillig ontregelen van voice- of tekstkanalen zijn verboden.","path":"serverregels/#wrr-18"},{"title":"Geen grensoverschrijdende RP","code":"WRR §19","context":"Roleplay & Serverregels","description":"Seksueel expliciete, intimiderende of anderszins onveilig aanvoelende scènes zijn niet toegestaan. Respecteer grenzen en stop wanneer betrokkenen bezwaar maken.","path":"serverregels/#wrr-19"},{"title":"Eerlijke beroeps-RP","code":"WRR §20","context":"Roleplay & Serverregels","description":"Jobhoppen om exclusieve spullen, functies of financiën over te dragen is niet toegestaan. Conflicterende rollen vereisen staffgoedkeuring.","path":"serverregels/#wrr-20"},{"title":"Supporttickets","code":"WRR §21","context":"Roleplay & Serverregels","description":"Maak een melding met beschikbare feitelijke informatie, tijdstip en betrokkenen. Vermijd publieke beschuldigingen.","path":"serverregels/#wrr-21"},{"title":"Bewijs en privacy","code":"WRR §22","context":"Roleplay & Serverregels","description":"Gebruik alleen rechtmatig gedeelde screenshots of clips voor rapportage. Persoonlijke gegevens van andere spelers mogen niet worden gepubliceerd.","path":"serverregels/#wrr-22"},{"title":"Staffbevoegdheid","code":"WRR §23","context":"Roleplay & Serverregels","description":"Staff behandelt OOC-conflicten onafhankelijk van in-game politie, OM en rechtbank. Een IC-vonnis is geen staffsanctie.","path":"serverregels/#wrr-23"},{"title":"Sanctieladder","code":"WRR §24","context":"Roleplay & Serverregels","description":"Bij overtreding kan staff waarschuwingen, tijdelijke beperkingen of bans inzetten afhankelijk van ernst, context en eerdere feiten. Ernstige schendingen kunnen direct tot een ban leiden.","path":"serverregels/#wrr-24"},{"title":"Bezwaar tegen moderatie","code":"WRR §25","context":"Roleplay & Serverregels","description":"Een betrokkene kan via de officieel aangekondigde route een herbeoordeling aanvragen. Medewerkers behandelen bezwaar zorgvuldig en zonder vergelding.","path":"serverregels/#wrr-25"},{"title":"Justitie & Rechtspraak","code":"Judicial Branch · WJR","context":"Justitie","description":"Transparante structuur voor District Court, District Attorney, advocatuur en griffie.","path":"rechtspraak/"},{"title":"District Court","code":"WJR §101","context":"Justitie & Rechtspraak","description":"De District Court behandelt in eerste aanleg strafzaken, civiele zaken en verzoeken om rechterlijke bevelen.","path":"rechtspraak/#wjr-101"},{"title":"Appeals Court","code":"WJR §102","context":"Justitie & Rechtspraak","description":"Een andere rechter dan de rechter die de oorspronkelijke zaak afdeed behandelt gemotiveerde beroepsverzoeken.","path":"rechtspraak/#wjr-102"},{"title":"District Attorney’s Office","code":"WJR §103","context":"Justitie & Rechtspraak","description":"De aanklager vertegenwoordigt de staat, beoordeelt bewijs, beslist over tenlastelegging en vordert gemotiveerde straffen.","path":"rechtspraak/#wjr-103"},{"title":"Defense Counsel","code":"WJR §104","context":"Justitie & Rechtspraak","description":"Een advocaat verdedigt onafhankelijk de belangen van de cliënt en heeft recht op redelijke inzage in relevante stukken.","path":"rechtspraak/#wjr-104"},{"title":"Court Clerk","code":"WJR §105","context":"Justitie & Rechtspraak","description":"De griffier bewaakt de dossieradministratie, houdt besluiten bij, plant zittingen en verzorgt officiële communicatie.","path":"rechtspraak/#wjr-105"},{"title":"Rechterlijke onafhankelijkheid","code":"WJR §106","context":"Justitie & Rechtspraak","description":"Een rechter neemt geen instructies over de inhoud van een zaak aan van politie, aanklager, bestuur of staff.","path":"rechtspraak/#wjr-106"},{"title":"Aanmelding van zaak","code":"WJR §201","context":"Justitie & Rechtspraak","description":"De aanklager levert feiten, wetsartikelen, bewijslijst en procesdeelnemers aan de griffie.","path":"rechtspraak/#wjr-201"},{"title":"Voorbereiding","code":"WJR §202","context":"Justitie & Rechtspraak","description":"De griffier deelt de stukken, zittingsdatum en procedurele afspraken met aanklager en verdediging.","path":"rechtspraak/#wjr-202"},{"title":"Zitting","code":"WJR §203","context":"Justitie & Rechtspraak","description":"De rechter opent de zaak, verifieert de beschuldiging, hoort beide partijen, beoordeelt bewijs en geeft gelegenheid tot repliek.","path":"rechtspraak/#wjr-203"},{"title":"Uitspraak en registratie","code":"WJR §204","context":"Justitie & Rechtspraak","description":"De uitspraak vermeldt de bewezenverklaring, toepasselijke wet, motivering en eventuele straf of schadevergoeding.","path":"rechtspraak/#wjr-204"},{"title":"Mediation","code":"WJR §205","context":"Justitie & Rechtspraak","description":"Partijen kunnen civiele geschillen met een mediator bespreken. Een strafrechtelijk vonnis wordt niet vervangen door een geheime overeenkomst zonder wettige basis.","path":"rechtspraak/#wjr-205"},{"title":"Belangenconflict","code":"WJR §301","context":"Justitie & Rechtspraak","description":"Een rechter of aanklager die persoonlijk betrokken is bij de zaak meldt dat onmiddellijk en trekt zich terug indien onafhankelijkheid niet gewaarborgd is.","path":"rechtspraak/#wjr-301"},{"title":"Pro-deobijstand","code":"WJR §302","context":"Justitie & Rechtspraak","description":"Wie onvoldoende financiële middelen heeft kan, binnen de gepubliceerde Westaris-regeling, kosteloze of gesubsidieerde rechtsbijstand aanvragen.","path":"rechtspraak/#wjr-302"},{"title":"Vertrouwelijkheid","code":"WJR §303","context":"Justitie & Rechtspraak","description":"Vertrouwelijke cliëntcommunicatie wordt beschermd, behalve voor zover wet en rechtmatige procesbeslissingen anders bepalen.","path":"rechtspraak/#wjr-303"},{"title":"Tuchtklacht","code":"WJR §304","context":"Justitie & Rechtspraak","description":"Klachten tegen juristen, aanklagers en rechters worden onafhankelijk beoordeeld volgens een vooraf bekendgemaakt reglement.","path":"rechtspraak/#wjr-304"},{"title":"Business & Civil Code","code":"Bedrijfsrecht en overeenkomsten · WBC","context":"Bestuur & RP","description":"Praktische fictieve Amerikaanse regels voor bedrijven, contracten, vergunningen en aansprakelijkheid.","path":"bedrijfsrecht/"},{"title":"Registratie","code":"WBC §101","context":"Business & Civil Code","description":"Een onderneming wordt geregistreerd bij het aangewezen Business Registry van Westaris en ontvangt een uniek registratienummer.","path":"bedrijfsrecht/#wbc-101"},{"title":"Business License","code":"WBC §102","context":"Business & Civil Code","description":"Een onderneming die een gereguleerde dienst aanbiedt vraagt vooraf een passende gemeentelijke of staatsvergunning aan.","path":"bedrijfsrecht/#wbc-102"},{"title":"Zakelijke administratie","code":"WBC §103","context":"Business & Civil Code","description":"Een ondernemer houdt basisgegevens over eigendom, vergunningen, zakelijke inkomsten en contracten voldoende controleerbaar bij.","path":"bedrijfsrecht/#wbc-103"},{"title":"Misleidende reclame","code":"WBC §104","context":"Business & Civil Code","description":"Doelbewust aantoonbaar onjuiste informatie geven over een wezenlijk kenmerk van een product of dienst is verboden.","path":"bedrijfsrecht/#wbc-104"},{"title":"Eerlijke dienstverlening","code":"WBC §105","context":"Business & Civil Code","description":"Zonder geldige contractuele of wettelijke grond mogen gekochte goederen of diensten niet willekeurig worden onthouden.","path":"bedrijfsrecht/#wbc-105"},{"title":"Contracten","code":"WBC §201","context":"Business & Civil Code","description":"Een overeenkomst is geldig wanneer partijen bevoegd zijn, voldoende duidelijk instemmen en de afspraak geen verboden doel dient.","path":"bedrijfsrecht/#wbc-201"},{"title":"Aansprakelijkheid","code":"WBC §202","context":"Business & Civil Code","description":"Wie door verwijtbaar handelen schade aan een ander veroorzaakt, kan tot redelijke vergoeding worden verplicht. Bewijs van causaliteit en schade is vereist.","path":"bedrijfsrecht/#wbc-202"},{"title":"Eigendomsoverdracht","code":"WBC §203","context":"Business & Civil Code","description":"Eigendom gaat over volgens een aantoonbare afspraak, geldige betaling en toepasselijke registratieregels.","path":"bedrijfsrecht/#wbc-203"},{"title":"Geschilbeslechting","code":"WBC §204","context":"Business & Civil Code","description":"Zakelijke en civiele geschillen worden in eerste instantie besproken of via bemiddeling opgelost; zo nodig beslist de District Court.","path":"bedrijfsrecht/#wbc-204"},{"title":"Faillissement en opheffing","code":"WBC §205","context":"Business & Civil Code","description":"Een onderneming kan na een gemotiveerde bestuurlijke of rechterlijke procedure worden beëindigd. Openstaande verplichtingen worden volgens een gepubliceerde regeling afgewikkeld.","path":"bedrijfsrecht/#wbc-205"},{"title":"Taxes & State Fees","code":"Belastingen en heffingen · WTC","context":"Bestuur & RP","description":"Transparante belastingen, met expliciet als concept gemarkeerde voorbeeldtarieven.","path":"belastingen/"},{"title":"Wettelijke basis","code":"WTC §101","context":"Taxes & State Fees","description":"Er wordt alleen een IC-belasting of heffing geïnd als de grondslag, het tarief en de betaaltermijn publiek zijn vastgelegd.","path":"belastingen/#wtc-101"},{"title":"Vehicle Registration Fee","code":"WTC §102","context":"Taxes & State Fees","description":"Voor een geregistreerd particulier voertuig kan periodiek een wegen- of registratieheffing gelden. De hoogte volgt uitsluitend uit een gepubliceerd tarievenbesluit.","path":"belastingen/#wtc-102"},{"title":"Business Tax","code":"WTC §103","context":"Taxes & State Fees","description":"Geregistreerde bedrijven kunnen op grond van een gepubliceerde regeling een omzet- of winstgerelateerde heffing betalen.","path":"belastingen/#wtc-103"},{"title":"Vrijstelling dienstvoertuigen","code":"WTC §104","context":"Taxes & State Fees","description":"Officieel geregistreerde dienstvoertuigen van openbare hulpdiensten kunnen worden vrijgesteld van particuliere voertuigbelasting.","path":"belastingen/#wtc-104"},{"title":"Geen willekeurige naheffing","code":"WTC §105","context":"Taxes & State Fees","description":"Onbetaalde bedragen worden niet verdubbeld zonder gepubliceerde regeling en redelijke mogelijkheid tot betwisting.","path":"belastingen/#wtc-105"},{"title":"Concepttarieven","code":"Tabel","context":"Taxes & State Fees","description":" Voertuigregistratie (eenmalig) $500 Concept Periodieke voertuigheffing $150 per ingame-belastingcyclus Concept Business License $2.500 Concept Vergunning evenement $1.000 Concept Vliegbrevet aanvraag $1.500 Concept","path":"belastingen/"},{"title":"Tarievenbesluit","code":"WTC §201","context":"Taxes & State Fees","description":"De administratie publiceert de definitieve tarieven en ingangsdatum afzonderlijk. Een conceptbedrag is geen zelfstandig afdwingbare verplichting.","path":"belastingen/#wtc-201"},{"title":"Boetes & Strafklassen","code":"Law Enforcement · tarievenoverzicht","context":"Diensten & tarieven","description":"Een snel raadpleegbare strafmatrix voor politie en justitie, met consistente Amerikaanse dollars.","path":"kosten/politie/"},{"title":"Algemene klassen","code":"Tabel","context":"Boetes & Strafklassen","description":" Infraction $100 – $2.500 0 Misdemeanor C $500 – $5.000 0 – 10 Misdemeanor B $1.000 – $10.000 0 – 20 Misdemeanor A $2.500 – $20.000 0 – 30 Felony D $10.000 – $35.000 20 – 45","path":"kosten/politie/"},{"title":"Controle op feitcodes","code":"WLE §101","context":"Boetes & Strafklassen","description":"Iedere boete of arrestatie wordt gekoppeld aan een concrete feitcode, eigen waarneming of betrouwbaar bewijsmateriaal en korte toelichting.","path":"kosten/politie/#wle-101"},{"title":"Geen automatische maximumstraf","code":"WLE §102","context":"Boetes & Strafklassen","description":"Hoge strafklassen betekenen niet dat iedere verdachte het maximale bedrag of de maximale tijd krijgt.","path":"kosten/politie/#wle-102"},{"title":"Verkeersboetes","code":"WLE §103","context":"Boetes & Strafklassen","description":"Voor snelheid, parkeren, verlichting en andere concrete verkeersovertredingen wordt eerst de Vehicle Code geraadpleegd.","path":"kosten/politie/#wle-103"},{"title":"Veelvoorkomende bekeuringen","code":"Tabel","context":"Boetes & Strafklassen","description":" 10–19 mph te hard $750 20–29 mph te hard $1.500 Rood verkeerslicht negeren $500 Onrechtmatig parkeren bij nooduitgang $750 Geen geldig kenteken $600","path":"kosten/politie/"},{"title":"Advocatuur & Rechtsbijstand","code":"Defense Counsel · tarieven","context":"Diensten & tarieven","description":"Juridische ondersteuning in Westaris, inclusief een heldere conceptprijslijst en pro-deomogelijkheid.","path":"kosten/advocatuur/"},{"title":"Vrije advocaatkeuze","code":"WLA §101","context":"Advocatuur & Rechtsbijstand","description":"Een verdachte of civiele partij mag een beschikbare bevoegde advocaat kiezen. De advocaat vertegenwoordigt de cliënt onafhankelijk.","path":"kosten/advocatuur/#wla-101"},{"title":"Kostenafspraak","code":"WLA §102","context":"Advocatuur & Rechtsbijstand","description":"Een advocaat maakt vooraf duidelijk welk tarief, welke tijdseenheid en welke aanvullende kosten gelden.","path":"kosten/advocatuur/#wla-102"},{"title":"Pro-deo","code":"WLA §103","context":"Advocatuur & Rechtsbijstand","description":"Bij aantoonbare ontoereikende middelen kan de cliënt de gepubliceerde subsidieregeling voor bijstand aanvragen.","path":"kosten/advocatuur/#wla-103"},{"title":"Voorstel voor tarieven","code":"Tabel","context":"Advocatuur & Rechtsbijstand","description":" Consult van 15 RP-minuten $750 Concept Verhoorbijstand per 15 RP-minuten $1.000 Concept Contract beoordelen $2.000 Concept Vertegenwoordiging rechtszitting $5.000 Concept Pro-deobijstand $0 voor cliënt Bij goedgekeurde aanvraag","path":"kosten/advocatuur/"},{"title":"Wijzigbaarheid","code":"WLA §104","context":"Advocatuur & Rechtsbijstand","description":"Dit zijn richtprijzen voor de RP-economie. Het bestuursbesluit of de schriftelijke overeenkomst bepaalt het definitieve tarief.","path":"kosten/advocatuur/#wla-104"},{"title":"Emergency Medical Services","code":"EMS · medische zorg en kosten","context":"Diensten & tarieven","description":"Duidelijke afspraken voor EMS-zorg en concepttarieven die op de roleplay-economie kunnen worden afgestemd.","path":"kosten/ambulance/"},{"title":"Spoedhulp","code":"WEMS §101","context":"Emergency Medical Services","description":"Bij een acuut noodgeval gaat noodzakelijke hulpverlening voor op administratieve afhandeling en facturatie.","path":"kosten/ambulance/#wems-101"},{"title":"Vertrouwelijke gegevens","code":"WEMS §102","context":"Emergency Medical Services","description":"Medische informatie wordt niet zonder grond gedeeld met onbevoegde partijen.","path":"kosten/ambulance/#wems-102"},{"title":"Zorgverzekeringsregeling","code":"WEMS §103","context":"Emergency Medical Services","description":"Als Westaris een zorgverzekering invoert, publiceert het bestuur vooraf dekking, premies, vergoedingen en uitzonderingen.","path":"kosten/ambulance/#wems-103"},{"title":"Conceptprijzen voor de RP","code":"Tabel","context":"Emergency Medical Services","description":" Eerste medische controle $250 Ambulancerit $1.000 Standaardbehandeling $1.500 Uitgebreide ziekenhuisbehandeling $3.500 EHBO-cursus $1.000","path":"kosten/ambulance/"},{"title":"Publicatie definitieve tarieven","code":"WEMS §104","context":"Emergency Medical Services","description":"EMS past alleen de definitief vastgestelde en gepubliceerde tarieven toe; bovenstaande prijzen zijn voorstellen.","path":"kosten/ambulance/#wems-104"},{"title":"Roadside Assistance","code":"Pechhulp & berging · tarieven","context":"Diensten & tarieven","description":"Eerlijke concepttarieven voor pechhulp, reparatie en berging in de staat Westaris.","path":"kosten/anwb/"},{"title":"Aanvraag en toestemming","code":"WRSA §101","context":"Roadside Assistance","description":"Niet-spoedeisende reparatie en berging vinden plaats na toestemming van de voertuigeigenaar of een bevoegde opdrachtgever.","path":"kosten/anwb/#wrsa-101"},{"title":"Berging op overheidsverzoek","code":"WRSA §102","context":"Roadside Assistance","description":"Een bevoegde dienst kan op grond van de wet berging of veiligstelling opdragen. De aanleiding wordt genoteerd.","path":"kosten/anwb/#wrsa-102"},{"title":"Conceptprijzen","code":"Tabel","context":"Roadside Assistance","description":" Starthulp $300 $500 Kleine reparatie $600 $900 Grote reparatie $1.500 $2.000 Berging $1.200 $1.800 Spoedtoeslag $250 $350","path":"kosten/anwb/"},{"title":"Geen verborgen kosten","code":"WRSA §103","context":"Roadside Assistance","description":"Aanvullende kosten worden vooraf duidelijk gemaakt, tenzij onmiddellijke veiligheidsmaatregelen dat onmogelijk maken.","path":"kosten/anwb/#wrsa-103"},{"title":"Vliegschool & Brevetten","code":"Flight Training · tarieven","context":"Diensten & tarieven","description":"Nederlandstalige Amerikaanse vliegopleiding met een overzicht van fictieve cursusprijzen.","path":"kosten/vliegschool/"},{"title":"Brevetvereiste","code":"WFS §101","context":"Vliegschool & Brevetten","description":"Een piloot mag alleen een vliegcategorie bedienen waarvoor de vereiste RP-bevoegdheid is afgegeven.","path":"kosten/vliegschool/#wfs-101"},{"title":"Veilig vlieggedrag","code":"WFS §102","context":"Vliegschool & Brevetten","description":"Vliegschool en cursist respecteren de gepubliceerde veiligheidszones, NOTAMs en luchtvaartregels.","path":"kosten/vliegschool/#wfs-102"},{"title":"Conceptopleidingen","code":"Tabel","context":"Vliegschool & Brevetten","description":" Propellervliegtuig $15.000 Helikopter $20.000 Jet-aantekening $10.000 Stuntvlieg-aantekening $7.500 Hervatting / herexamen $2.500","path":"kosten/vliegschool/"},{"title":"Definitieve prijs","code":"WFS §103","context":"Vliegschool & Brevetten","description":"De vliegschool bevestigt de actuele goedgekeurde opleidingsprijs vooraf schriftelijk.","path":"kosten/vliegschool/#wfs-103"},{"title":"Aviation & NOTAM","code":"Luchtruimbeperkingen · WAC","context":"Verkeer & gebieden","description":"Luchtruimregels zonder fictieve kaartlocaties of overgenomen gebiedskaarten van een andere stad.","path":"notam/"},{"title":"Vliegbevoegdheid","code":"WAC §101","context":"Aviation & NOTAM","description":"Voor de betreffende categorie luchtvaartuig is een passend brevet verplicht waar de staat dit heeft vastgesteld.","path":"notam/#wac-101"},{"title":"No-fly zones","code":"WAC §102","context":"Aviation & NOTAM","description":"Een vliegverbod is alleen handhaafbaar als gebied, hoogte, geldigheidsduur en bekendmaking voldoende duidelijk zijn.","path":"notam/#wac-102"},{"title":"Gevoelige locaties","code":"WAC §103","context":"Aviation & NOTAM","description":"Militaire locaties, gevangenissen en operationele hulpdienstgebieden kunnen via een gepubliceerd NOTAM tijdelijk of permanent worden beperkt.","path":"notam/#wac-103"},{"title":"Noodvluchten","code":"WAC §104","context":"Aviation & NOTAM","description":"Een bevoegde noodvlucht kan onder een uitdrukkelijke uitzondering opereren, zolang veiligheid en communicatie gewaarborgd blijven.","path":"notam/#wac-104"},{"title":"Actuele publicatie","code":"WAC §105","context":"Aviation & NOTAM","description":"Staff of de bevoegde luchtvaartdienst beheert de officiële Westaris-NOTAM-lijst. Kaarten van andere steden hebben geen geldigheid.","path":"notam/#wac-105"},{"title":"NOTAM-registratie","code":"Tabel","context":"Aviation & NOTAM","description":" Gebiedsnaam en kaartcoördinaten Ja Hoogtebereik (feet) Ja Begin- en einddatum Ja Reden en verantwoordelijke dienst Ja Eventuele hulpdienstuitzondering Indien van toepassing","path":"notam/"},{"title":"Public Safety Zones","code":"Risicogebieden · WPSZ","context":"Verkeer & gebieden","description":"Juridische kaders voor bijzondere veiligheidsgebieden zonder verzonnen Westaris-locaties.","path":"risico-gebieden/"},{"title":"Aanwijzing","code":"WPSZ §101","context":"Public Safety Zones","description":"Een risicogebied vereist een schriftelijk besluit van de bevoegde autoriteit met gebied, motivering, tijdsduur en controlebevoegdheid.","path":"risico-gebieden/#wpsz-101"},{"title":"Bekendmaking","code":"WPSZ §102","context":"Public Safety Zones","description":"De aanwijzing wordt op het officiële Westaris-portaal en zo nodig de RP-kaart gepubliceerd vóór handhaving.","path":"risico-gebieden/#wpsz-102"},{"title":"Bevoegdheden blijven beperkt","code":"WPSZ §103","context":"Public Safety Zones","description":"Ook in een risicogebied blijven de constitutionele beginselen en regels uit de Criminal Procedure Code gelden.","path":"risico-gebieden/#wpsz-103"},{"title":"Toezicht","code":"WPSZ §104","context":"Public Safety Zones","description":"Een rechter kan de proportionaliteit en rechtmatigheid van een concrete controle beoordelen.","path":"risico-gebieden/#wpsz-104"},{"title":"Border & Customs Control","code":"Douane- en grenszones · WBCZ","context":"Verkeer & gebieden","description":"Een logisch Amerikaans aandoend douanesysteem dat pas geografisch werkt na officiële aanwijzing.","path":"douanegebieden/"},{"title":"Aangewezen grensposten","code":"WBCZ §101","context":"Border & Customs Control","description":"Een grenscontrolepost is alleen officieel als locatie, reikwijdte en bevoegde uitvoerder bekend zijn gemaakt.","path":"douanegebieden/#wbcz-101"},{"title":"Controlebevoegdheid","code":"WBCZ §102","context":"Border & Customs Control","description":"Een controle moet overeenkomen met de gepubliceerde regeling en mag niet ontaarden in willekeurige doorzoeking.","path":"douanegebieden/#wbcz-102"},{"title":"Valse documenten","code":"WBCZ §103","context":"Border & Customs Control","description":"Het bewust verstrekken van vervalste douane- of registratiedocumenten kan vallen onder WPC §109.","path":"douanegebieden/#wbcz-103"},{"title":"Bezwaar en registratie","code":"WBCZ §104","context":"Border & Customs Control","description":"Controles met beslag of andere ingrijpende gevolgen worden geregistreerd; betrokkenen krijgen een mogelijkheid tot toetsing.","path":"douanegebieden/#wbcz-104"},{"title":"Offroad & Vehicle Classes","code":"Wegtypen en terreinrijden · WOC","context":"Verkeer & gebieden","description":"Overzicht van Amerikaanse wegtypen en regels voor terreinvoertuigen.","path":"offroadvoertuigen/"},{"title":"Wegclassificatie","code":"Tabel","context":"Offroad & Vehicle Classes","description":" P Verharde openbare weg Asfalt, beton D Aangewezen onverharde weg Duidelijk zand- of grindpad X Niet-aangewezen terrein Gras, duinen of afgesloten terrein","path":"offroadvoertuigen/"},{"title":"Voertuiggeschiktheid","code":"WOC §101","context":"Offroad & Vehicle Classes","description":"Een voertuig moet geschikt en toegelaten zijn voor het wegtype waarop het wordt gebruikt.","path":"offroadvoertuigen/#woc-101"},{"title":"Terreintoestemming","code":"WOC §102","context":"Offroad & Vehicle Classes","description":"Rijden buiten aangewezen paden vereist toestemming wanneer het terrein beschermd of privé is.","path":"offroadvoertuigen/#woc-102"},{"title":"Veiligheid","code":"WOC §103","context":"Offroad & Vehicle Classes","description":"Terreinrijden dat aantoonbaar omstanders in gevaar brengt, valt ook onder de algemene verkeerswet.","path":"offroadvoertuigen/#woc-103"},{"title":"Lijst met speciale voertuigen","code":"WOC §104","context":"Offroad & Vehicle Classes","description":"Een concrete modellenlijst moet door het Westaris-bestuur worden gepubliceerd. Voertuiglijsten van andere steden worden niet automatisch toegestaan.","path":"offroadvoertuigen/#woc-104"},{"title":"Content Creators & Media","code":"Streamingbeleid · WRM","context":"Bestuur & RP","description":"Overzichtelijk streamingbeleid voor TikTok, Twitch, YouTube en andere platforms.","path":"streamen/"},{"title":"Streamen is toegestaan","code":"WRM §101","context":"Content Creators & Media","description":"Het livestreamen van RP is in beginsel toegestaan. Volg platformregels, privacyafspraken en de Westaris-serverregels.","path":"streamen/#wrm-101"},{"title":"Geen streamsniping","code":"WRM §102","context":"Content Creators & Media","description":"Gebruik een livestream niet om informatie te verkrijgen die jouw personage IC niet kan weten.","path":"streamen/#wrm-102"},{"title":"Privacy en persoonlijke gegevens","code":"WRM §103","context":"Content Creators & Media","description":"Deel geen echte persoonsgegevens, privéberichten, geheimen of identificeerbare informatie zonder toestemming.","path":"streamen/#wrm-103"},{"title":"Beschermen van lopende onderzoeken","code":"WRM §104","context":"Content Creators & Media","description":"Vertrouwelijke OOC-informatie van staff, meldingen en beveiligingsprocedures mogen niet worden gepubliceerd.","path":"streamen/#wrm-104"},{"title":"Clip als bewijs","code":"WRM §105","context":"Content Creators & Media","description":"Een clip kan bij support worden gebruikt; de context en authenticiteit blijven belangrijk. Publiceer geen beschuldigingen als vaststaand feit.","path":"streamen/#wrm-105"},{"title":"Contentgeschillen","code":"WRM §106","context":"Content Creators & Media","description":"Bij klachten kan staff een clip beoordelen, om aanvullende context vragen en passende maatregelen nemen.","path":"streamen/#wrm-106"}];